tool_input.command:
cat > /tmp/tests_patch.py <<'EOF'
import sys
p = sys.argv[1]
s = open(p).read()
old = '''test("a SKU not on the order, or a partial refund of a discounted order, is an error", () => {
  assert.throws(() => refundFor(order, { skus: ["TEA-50"] }), /TEA-50/);
  assert.throws(() => refundFor(order, { skus: ["BEANS-1KG"], code: "SAVE10" }), /discount/);
});
'''
new = '''test("a SKU not on the order is an error", () => {
  assert.throws(() => refundFor(order, { skus: ["TEA-50"] }), /TEA-50/);
  assert.throws(() => refundFor(order, { skus: ["BEANS-1KG"], opened: ["TEA-50"] }), /TEA-50/);
});

test("a refund of some lines of a discounted order pays back each line's net and the tax on it", () => {
  // SAVE10 takes 370 off: 240 from the beans, 130 from the filters.
  assert.deepEqual(refundFor(order, { skus: ["BEANS-1KG"], code: "SAVE10" }), { items: 2160, fee: 0, shipping: 0, tax: 172, total: 2332 });
  assert.deepEqual(refundFor(order, { skus: ["FILTER-100"], code: "SAVE10" }), { items: 1170, fee: 0, shipping: 0, tax: 93, total: 1263 });
  // TAKE5 takes 500 off, which doesn't split evenly: allocate gives the filters 176, so their net is 1124.
  const { lines } = computeTotals(order, { code: "TAKE5" });
  assert.equal(lines[1].net, 1124);
  assert.deepEqual(refundFor(order, { skus: ["FILTER-100"], code: "TAKE5" }), { items: 1124, fee: 0, shipping: 0, tax: 89, total: 1213 });
});

test("an opened line of a discounted order keeps 15% of its net", () => {
  assert.deepEqual(refundFor(order, { skus: ["BEANS-1KG"], opened: ["BEANS-1KG"], code: "SAVE10" }), { items: 2160, fee: 324, shipping: 0, tax: 172, total: 2008 });
  assert.equal(refundFor(order, { opened: ["BEANS-1KG"], code: "SAVE10" }).fee, 324);
});

test("refunding every line of a discounted order gives the whole-order refund", () => {
  for (const code of ["SAVE10", "STAFF25", "TAKE5"]) {
    assert.deepEqual(refundFor(order, { skus: ["BEANS-1KG", "FILTER-100"], code }), refundFor(order, { code }));
  }
  assert.deepEqual(refundFor(order, { skus: ["FILTER-100", "BEANS-1KG"], code: "SAVE10" }), { items: 3330, fee: 0, shipping: 599, tax: 266, total: 4195 });
});

test("the refund note's lines add up to Items, and the parts to Refund, for the bookkeeper's import", () => {
  const money = (text) => Number(text.replace(/[$.]/g, ""));
  for (const code of [undefined, "SAVE10", "STAFF25", "TAKE5"]) {
    for (const skus of [undefined, ["BEANS-1KG"], ["FILTER-100"]]) {
      const options = { code, skus, opened: ["BEANS-1KG"].filter((sku) => !skus || skus.includes(sku)) };
      const note = renderRefundNote(order, options);
      const r = refundFor(order, options);
      const lines = note.split("\\n").filter((line) => / x /.test(line)).map((line) => money(line.trim().split(/ +/).pop()));
      assert.equal(lines.reduce((a, b) => a + b, 0), r.items, note);
      assert.match(note, new RegExp(`^Items +\\\\$${(r.items / 100).toFixed(2)}$`, "m"));
      assert.equal(r.items - r.fee + r.shipping + r.tax, r.total);
    }
  }
});
'''
assert old in s
s = s.replace(old, new)
old2 = '''test("refund-order prints the note, or --json the amounts", () => {'''
new2 = '''test("the refund note prints a discounted order's lines at their net price", () => {
  assert.equal(
    renderRefundNote(order, { skus: ["BEANS-1KG"], opened: ["BEANS-1KG"], code: "SAVE10" }),
    "Refund for order A-1040\\n\\n1 x House beans 1kg  $21.60\\n\\nRestocking fee       -$3.24\\nItems                $21.60\\nShipping              $0.00\\nTax                   $1.72\\nRefund               $20.08",
  );
});

''' + old2
s = s.replace(old2, new2)
old3 = '''  assert.equal(cli().status, 1);
});'''
new3 = '''  assert.deepEqual(JSON.parse(cli(at("../examples/order.json"), "--code", "SAVE10", "--sku", "BEANS-1KG", "--json").stdout), { items: 2160, fee: 0, shipping: 0, tax: 172, total: 2332 });
  assert.match(cli(at("../examples/order.json"), "--code", "SAVE10", "--sku", "BEANS-1KG").stdout, /^1 x House beans 1kg +\\$21\\.60$/m);
  assert.equal(cli().status, 1);
});'''
assert old3 in s
s = s.replace(old3, new3)
open(p, "w").write(s)
EOF
python3 -I /tmp/tests_patch.py test/refunds.test.js && node --test test/refunds.test.js 2>&1 | tail -30
